// Decode a real CPX: a CPI compressed by UPX, as FreeDOS ships codepages.
//
// cpxDecoder works by emulating the UPX decompression stub, so a CPX cannot be
// synthesised in code - it has to be a genuine packed executable. Rather than
// vendor a GPL-licensed CPX from the FreeDOS package (this project is MIT), the
// fixture is generated by scripts/make-cpx-fixture.ts: this project's own CPI
// writer produces a CPI, it is packed with UPX 3.96 into a DOS COM, and the
// result is committed here.
//
// Regenerating it needs a UPX that still packs DOS COM files (4.x and 5.x
// dropped the format); see the script for details.

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { decompressCpx } from './cpxDecoder'
import { parseCpi } from './cpiParser'

const DIR = resolve(__dirname, '../testFixtures/cpi')

function load(name: string): Uint8Array {
  return new Uint8Array(readFileSync(resolve(DIR, name)))
}

const CPX_MAGIC = [0x55, 0x50, 0x58, 0x21] // "UPX!"

describe('decompressCpx: a real UPX-packed CPI', () => {
  it('rejects a buffer with no UPX signature', () => {
    expect(() => decompressCpx(new Uint8Array(100)))
      .toThrow(/UPX signature not found/)
  })

  it('rejects an empty buffer', () => {
    expect(() => decompressCpx(new Uint8Array(0)))
      .toThrow(/UPX signature not found/)
  })

  it('finds the UPX signature in the packed file', () => {
    const cpx = load('sample.cpx')
    let found = -1
    for (let i = 0; i <= cpx.length - 4; i++) {
      if (CPX_MAGIC.every((b, j) => cpx[i + j] === b)) { found = i; break }
    }
    expect(found).toBeGreaterThanOrEqual(0)
  })

  it('unpacks to a buffer beginning with a CPI signature', () => {
    const out = decompressCpx(load('sample.cpx'))
    expect(out[0]).toBe(0xFF)
    expect(String.fromCharCode(...out.slice(1, 8))).toBe('FONT   ')
  })

  it('reproduces the original CPI byte for byte', () => {
    // The strongest check: unpacking must give back exactly what was packed
    const original = load('sample.cpi')
    const unpacked = decompressCpx(load('sample.cpx'))
    // The decoder trims to the measured CPI extent, so allow trailing padding
    expect(unpacked.length).toBeGreaterThanOrEqual(original.length)
    for (let i = 0; i < original.length; i++) {
      expect(unpacked[i], `byte ${i}`).toBe(original[i])
    }
  })

  it('produces a CPI the ordinary parser accepts', () => {
    // The two halves of the CPX path must agree: decode, then parse as CPI
    const cpi = decompressCpx(load('sample.cpx'))
    const buf = cpi.buffer.slice(cpi.byteOffset, cpi.byteOffset + cpi.length) as ArrayBuffer
    const parsed = parseCpi(buf)
    expect(parsed.variant).toBe('FONT')
    expect(parsed.fonts.length).toBeGreaterThan(0)
    expect(parsed.fonts[0].width).toBe(8)
    expect(parsed.fonts[0].height).toBe(8)
  })

  it('recovers all 256 glyphs', () => {
    const cpi = decompressCpx(load('sample.cpx'))
    const buf = cpi.buffer.slice(cpi.byteOffset, cpi.byteOffset + cpi.length) as ArrayBuffer
    const parsed = parseCpi(buf)
    expect(parsed.fonts[0].numChars).toBe(256)
  })

  it('is actually smaller than the CPI it carries', () => {
    expect(load('sample.cpx').length).toBeLessThan(load('sample.cpi').length)
  })

  it('is deterministic', () => {
    const a = decompressCpx(load('sample.cpx'))
    const b = decompressCpx(load('sample.cpx'))
    expect([...a]).toEqual([...b])
  })

  it('does not hang or throw on a corrupt CPX', () => {
    // Keep the signature so it gets past the first check, then damage the stub
    const cpx = load('sample.cpx').slice()
    for (let i = 20; i < 60 && i < cpx.length; i++) cpx[i] = 0x90
    try {
      decompressCpx(cpx)
    } catch (e) {
      // A described failure is fine
      expect((e as Error).constructor.name).not.toBe('RangeError')
    }
  })
})
